    desc: `Langkat, 23–24 Januari 2025 — Mandiri Sahabat Desa bersama Crustea telah sukses menggelar kegiatan <i>Capacity Building</i> dan <i>Women Empowerment</i> di Langkat, Sumatera Utara. Acara ini berhasil menarik perhatian para pembudidaya udang beserta istri mereka.<br><br>

Pada 23 Januari 2025, acara dibuka dengan menyanyikan lagu Indonesia Raya, dilanjutkan sambutan oleh Bapak Agung Tritantyo, S.STP, M.AP selaku Camat Pangkalan Susu, Langkat, dan Ibu Roikhanatun Nafi’ah selaku Founder & CEO Crustea Indonesia. Sebelum sesi <i>Capacity Building in Aquaculture</i> dimulai, sebanyak 53 peserta dari 7 desa (Alur Cempedak, Sei Meran, Sei Siur, Beras Basah, Pangkalan Berandan, Pangkalan Susu, dan Pulau Sembilan) diajak untuk mengerjakan beberapa studi kasus terkait proses budidaya udang.<br><br>

Dalam penyampaian materi, peserta mendapatkan wawasan mengenai penerapan <b>teknologi Smart IoT</b> dan <b>energi terbarukan</b> dalam budidaya. Teknologi berbasis IoT ini membantu petambak memantau kualitas air tambak secara daring, efisien, dan akurat — sehingga dapat menghemat biaya operasional sekaligus meningkatkan respons terhadap perubahan kualitas air. Berdasarkan hasil evaluasi, lebih dari 80% peserta mengalami peningkatan pengetahuan, dan 53% berencana memperbaiki praktik budidaya mereka.<br><br>

<img src="/images/landing/blog/blog45/Picture2.png" class="img-rounded" alt="Crustea Program"><br><br>

Acara <b>Women Empowerment</b> pada 24 Januari 2025 dihadiri oleh 44 perempuan yang merupakan istri para petambak. Mereka mendapatkan pelatihan tentang <b>Digital Marketing</b>, <b>Branding Produk</b>, serta kreasi pengolahan hasil budidaya udang seperti dimsum dan kaldu udang. Kegiatan berlangsung interaktif dan ditutup dengan sesi kesan-pesan serta foto bersama.<br><br>

<img src="/images/landing/blog/blog45/Picture3.png" class="img-rounded" alt="Crustea Women Empowerment"><br><br>

“Crustea tidak hanya melihat dari sisi operasional tambak saja, namun juga dari hasil olahannya, agar petambak dapat meraih keuntungan optimal dan memiliki kemampuan mengolah hasil tambak,” ujar Roikhanatun Nafi’ah, CEO & Co-Founder Crustea.<br><br>

Dengan keberhasilan acara ini, Crustea berencana melanjutkan program serupa di berbagai wilayah lain untuk memperluas dampak positif bagi industri perikanan Indonesia.<br><br>

<b>Tentang Crustea</b><br>
Crustea adalah perusahaan yang berdedikasi untuk mendukung keberhasilan budidaya udang melalui inovasi teknologi dan program pemberdayaan. Produk unggulannya seperti EBII System, Panel Surya, Smart Energy, Eco-Aerator, dan Aerator Mini mampu mengurangi biaya listrik dan bahan bakar hingga 80% melalui sistem Smart IoT dan panel surya yang efisien. Crustea terus berkomitmen membangun ekosistem berkelanjutan dari hulu ke hilir melalui akses teknologi, pendampingan, pembiayaan, dan pasar.<br><br>
`
